def Enqueue(Data):
global Queue
global TailPointer
global HeadPointer
if TailPointer < 49:
TailPointer = TailPointer + 1
Queue[TailPointer] = Data
if HeadPointer == -1:
     HeadPointer = 0
return True
else:
return False
